"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3070],{34037:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"TrainClient","desc":"Client-side controller for train interaction. Discovers engine and brake\\nlever instances via `CollectionService` tags and wires their\\n`ProximityPrompt`s: engine prompts send `ReqRefuelTrain` (with early-out\\nnotifications for missing energy items or a full tank), and lever prompts\\nsend `ReqToggleBrake` while keeping their `ActionText` in sync with the\\ncurrent brake state. Incoming `TrainStateSync` packets are bridged into\\n`Signals.OnTrainStateChanged` so downstream controllers (e.g.\\n`MusicDirector`) never touch the network layer directly. Each incoming\\nsnapshot is also written to `TrainStateCache` before that signal fires, so\\na controller that subscribes late (e.g. `TrainFuelGuiController`) can still\\nrecover it.","realm":["Client"],"source":{"line":19,"path":"src/StarterPlayer/StarterPlayerScripts/TrainClient.client.luau"}}')}}]);